select id, category_id, sku_type, sku_name, img_url, per_limit, publish_status, check_status, is_new_person, sort,sku_code,price,market_price,stock,lock_stock,low_stock,sale,ware_id,create_time,update_time,is_deleted from sku_info
and id = #{skuId}
and stock-lock_stock > #{skuNum} for update
